import { useEffect, useState } from 'react';
import api from '../api';

function Chat() {
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState('');

  // TEMP (demo purpose)
  const senderId = 1;     // logged-in user
  const receiverId = 2;   // chatting with
  const batchId = null;   // null = personal chat

  useEffect(() => {
    api.get(`/chat/${senderId}`)
      .then(res => setMessages(res.data))
      .catch(() => {});
  }, []);

  const sendMessage = () => {
    if (!text) return;

    api.post('/chat', {
      sender_id: senderId,
      receiver_id: receiverId,
      batch_id: batchId,
      message_text: text
    })
    .then(() => {
      setMessages([...messages, {
        sender_id: senderId,
        message_text: text
      }]);
      setText('');
    });
  };

  return (
    <div>
      <h2>Chat</h2>

      <div>
        {messages.map((m, i) => (
          <p key={i}>
            <b>{m.sender_id === senderId ? 'Me' : 'User'}:</b> {m.message_text}
          </p>
        ))}
      </div>

      <input
        placeholder="Type message"
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}

export default Chat;
